#!/bin/bash
set -euo pipefail
umask 077
[[ $EUID -eq 0 ]] || exit 1
test -f /opt/football-github-sync/sync.py
systemctl stop football-github-sync.service
python3 - <<'PATCH'
from pathlib import Path
import base64,py_compile,os,shutil,time
p=Path('/opt/football-github-sync/sync.py')
backup=p.with_name('sync.py.before-json-fix-'+str(time.time_ns()))
shutil.copy2(p,backup)
tmp=p.with_suffix('.new');tmp.write_bytes(base64.b64decode(''))
py_compile.compile(str(tmp),doraise=True);tmp.chmod(0o600);os.replace(tmp,p)
print('SYNC_JSON_FIX_INSTALLED')
PATCH
systemctl start --no-block football-github-sync.service
echo '已在后台重新同步。查看：journalctl -u football-github-sync.service -n 15 --no-pager'
